values ($tenor${"client_name":"Halcyon Systems SA","freelancer_name":"Dana Whitfield","amount":18500,"currency":"USD","issue_date":"2026-08-05","due_date":"2026-09-19","payment_terms":"Net 45 from date of issue, fixed fee agreed in writing before commencement","payer_history":"First engagement between the parties; no prior invoices","payer_identifier":null,"deliverables":["Migration of the Halcyon order pipeline from batch to event-driven, including 31 integration tests passing at handover","Runbook and on-call escalation procedure, 24 pages","Two weeks of post-migration support, completed 4 August 2026"],"termination_clauses":["Termination for convenience requires 60 days written notice and does not affect fees for work completed and accepted before the notice date"],"late_penalty":"1.5% per month on overdue balances, per clause 7 of the signed statement of work","document_quality":88,"missing_critical_fields":["client company registration number","verifiable corporate footprint for the payer","confirmation of signatory authority"]}$tenor$, $tenor${"proposed_rate":92,"arguments":["The work is fully completed and delivered: the migration includes 31 passing integration tests, the runbook is 24 pages, and the two weeks of post-migration support ended on 4 August 2026, satisfying all performance obligations before the invoice date of 5 August 2026.","The payment terms are Net 45 from a fixed fee agreed in writing before commencement, and the termination clause states that termination for convenience requires 60 days written notice and does not affect fees for work completed and accepted before the notice date, preserving the freelancer's right to full payment.","A late penalty of 1.5% per month on overdue balances applies under clause 7 of the signed statement of work, giving the freelancer a contractual remedy for delayed payment and strengthening the expectation of timely collection.","The invoice is issued to a clearly named client, Halcyon Systems SA, and the docu